alter table public.notifications add column if not exists recipient_id uuid references public.profiles(id), add column if not exists related_type text, add column if not exists related_id uuid, add column if not exists dedupe_key text unique;
create index if not exists notifications_recipient_read_idx on public.notifications(recipient_id, is_read, created_at desc);
create table if not exists public.conversations (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now());
create table if not exists public.conversation_participants (conversation_id uuid not null references public.conversations(id) on delete cascade, profile_id uuid not null references public.profiles(id) on delete cascade, joined_at timestamptz not null default now(), primary key (conversation_id, profile_id));
create table if not exists public.private_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references public.profiles(id), recipient_id uuid not null references public.profiles(id), body text not null, client_message_id text, created_at timestamptz not null default now(), read_at timestamptz, unique(sender_id, client_message_id));
create index if not exists private_messages_conversation_created_idx on public.private_messages(conversation_id, created_at);
create index if not exists private_messages_recipient_read_idx on public.private_messages(recipient_id, read_at);
alter table public.conversations enable row level security;
alter table public.conversation_participants enable row level security;
alter table public.private_messages enable row level security;
create policy "participants can read conversations" on public.conversations for select to authenticated using (exists (select 1 from public.conversation_participants p where p.conversation_id = id and p.profile_id = auth.uid()));
create policy "participants can read membership" on public.conversation_participants for select to authenticated using (profile_id = auth.uid() or exists (select 1 from public.conversation_participants p where p.conversation_id = conversation_id and p.profile_id = auth.uid()));
create policy "participants can read private messages" on public.private_messages for select to authenticated using (sender_id = auth.uid() or recipient_id = auth.uid());
create policy "users can send private messages" on public.private_messages for insert to authenticated with check (sender_id = auth.uid() and exists (select 1 from public.conversation_participants p where p.conversation_id = conversation_id and p.profile_id = auth.uid()));
create policy "recipients can update read state" on public.private_messages for update to authenticated using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());
create policy "users can read own notifications" on public.notifications for select to authenticated using (recipient_id = auth.uid());
create policy "users can update own notifications" on public.notifications for update to authenticated using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());
